 "content": "def transform(grid):
    """Turn the non-background cells black and recolor the background by input color."""
    colors = {value for row in grid for value in row if value != 0}
    if len(colors) != 1:
        raise ValueError("expected exactly one non-background color")
    color = next(iter(colors))
    background_color = {3: 1, 8: 2}[color]
    return [[0 if value == color else background_color for value in row] for row in grid]
